def get_grouper(
    obj: FrameOrSeries,
    key=None,
    axis: int = 0,
    level=None,
    sort: bool = True,
    observed: bool = False,
    mutated: bool = False,
    validate: bool = True,
    dropna: bool = True,
) -> "Tuple[ops.BaseGrouper, List[Hashable], FrameOrSeries]":
    """
    Create and return a BaseGrouper, which is an internal
    mapping of how to create the grouper indexers.

    This function tries to figure out what the passing in references
    are and then creates a Grouping for each one, combined into
    a BaseGrouper.

    Parameters
    ----------
    obj : FrameOrSeries
        The object to be grouped.
    key : str, Grouper, or list-like, optional
        The grouping key(s).
    axis : int, default 0
        The axis to group along (0 for rows, 1 for columns).
    level : int or str, optional
        For MultiIndex, the level to group by.
    sort : bool, default True
        Whether to sort the groups.
    observed : bool, default False
        If categorical, only show observed values.
    mutated : bool, default False
        If the object has mutated.
    validate : bool, default True
        If True, validate for key/level overlaps.
    dropna : bool, default True
        Whether to drop NA values.

    Returns
    -------
    Tuple[ops.BaseGrouper, List[Hashable], FrameOrSeries]
        The created grouper, list of exclusions, and the object.
    """
    group_axis = obj._get_axis(axis)

    if level is not None:
        if isinstance(group_axis, MultiIndex):
            if is_list_like(level) and len(level) == 1:
                level = level[0]

            if key is None and is_scalar(level):
                key = group_axis.get_level_values(level)
                level = None
        else:
            if isinstance(level, str) and obj._get_axis(axis).name != level:
                raise ValueError(
                    f"level name {level} is not the name "
                    f"of the {obj._get_axis_name(axis)}"
                )
            if level not in range(len(group_axis)):
                raise ValueError(f"level {level} not valid for axis {axis}")
            level = None
            key = group_axis

    if isinstance(key, Grouper):
        binner, grouper, obj = key._get_grouper(obj, validate=False)
        if key.key is None:
            return grouper, [], obj
        else:
            return grouper, [key.key], obj

    elif isinstance(key, ops.BaseGrouper):
        return key, [], obj

    if not isinstance(key, list):
        keys = [key]
        match_axis_length = False
    else:
        keys = key
        match_axis_length = len(keys) == len(group_axis)

    any_callable = any(callable(g) or isinstance(g, dict) for g in keys)
    any_groupers = any(isinstance(g, Grouper) for g in keys)
    any_arraylike = any(
        isinstance(g, (list, tuple, Series, Index, np.ndarray)) for g in keys
    )

    if not any_callable and not any_arraylike and not any_groupers and match_axis_length and level is None:
        if isinstance(obj, DataFrame):
            all_in_columns_index = all(
                g in obj.columns or g in obj.index.names for g in keys
            )
        else:
            all_in_columns_index = all(g in obj.index.names for g in keys)

        if not all_in_columns_index:
            keys = [com.asarray_tuplesafe(keys)]

    if isinstance(level, (tuple, list)):
        if key is None:
            keys = [None] * len(level)
        levels = level
    else:
        levels = [level] * len(keys)

    groupings: List[Grouping] = []
    exclusions: List[Hashable] = []

    def is_in_axis(key) -> bool:
        if not _is_label_like(key):
            items = obj.axes[-1]
            try:
                items.get_loc(key)
            except (KeyError, TypeError, InvalidIndexError):
                return False
        return True

    def is_in_obj(gpr) -> bool:
        if not hasattr(gpr, "name"):
            return False
        try:
            return gpr is obj[gpr.name]
        except (KeyError, IndexError):
            return False

    for i, (gpr, level) in enumerate(zip(keys, levels)):
        if is_in_obj(gpr):
            in_axis, name = True, gpr.name
            exclusions.append(name)

        elif is_in_axis(gpr):
            if gpr in obj:
                if validate:
                    obj._check_label_or_level_ambiguity(gpr, axis=axis)
                in_axis, name, gpr = True, gpr, obj[gpr]
                exclusions.append(name)
            elif obj._is_level_reference(gpr, axis=axis):
                in_axis, name, level, gpr = False, None, gpr, None
            else:
                raise KeyError(gpr)
        else:
            in_axis, name = False, None

        if is_categorical_dtype(gpr) and len(gpr) != obj.shape[axis]:
            raise ValueError(
                f"Length of grouper ({len(gpr)}) and axis ({obj.shape[axis]}) "
                "must be the same length"
            )

        ping = (
            Grouping(
                group_axis,
                gpr,
                obj=obj,
                name=name,
                level=level,
                sort=sort,
                observed=observed,
                in_axis=in_axis,
                dropna=dropna,
            )
            if not isinstance(gpr, Grouping)
            else gpr
        )

        groupings.append(ping)

    if not groupings and len(obj):
        raise ValueError("No group keys passed!")
    elif not groupings:
        groupings.append(Grouping(Index([], dtype="int"), np.array([], dtype=np.intp)))

    grouper = ops.BaseGrouper(group_axis, groupings, sort=sort, mutated=mutated)
    return grouper, exclusions, obj
